from tactical_analyst.analytics.base import MatchContext
from tactical_analyst.schemas.event import MatchEvent

MATCH_ID = "match:analytics"
TEAM_A = "team:a"
TEAM_B = "team:b"
PLAYER_A1 = "player:a1"
PLAYER_A2 = "player:a2"
PLAYER_B1 = "player:b1"
PLAYER_B2 = "player:b2"


def event(
    event_id: str,
    team_id: str,
    event_type: str,
    *,
    index: int,
    timestamp_ms: int | None = None,
    player_id: str | None = None,
    receiver_player_id: str | None = None,
    outcome: str | None = None,
    possession_id: str | None = None,
    play_pattern: str | None = "Regular Play",
    x: float | None = None,
    y: float | None = None,
    end_x: float | None = None,
    end_y: float | None = None,
    xg: float | None = None,
    provider_payload: dict | None = None,
) -> MatchEvent:
    return MatchEvent(
        id=event_id,
        match_id=MATCH_ID,
        index=index,
        period=1,
        timestamp_ms=timestamp_ms if timestamp_ms is not None else index * 1000,
        team_id=team_id,
        player_id=player_id,
        receiver_player_id=receiver_player_id,
        event_type=event_type,
        event_subtype=None,
        outcome=outcome,
        possession_id=possession_id,
        play_pattern=play_pattern,
        x=x,
        y=y,
        end_x=end_x,
        end_y=end_y,
        xg=xg,
        under_pressure=None,
        related_event_ids=[],
        provider_payload=provider_payload or {},
    )


